import { chromium } from '/tmp/node_modules/playwright/index.mjs';
import fs from 'node:fs';

const shotDir = '/tmp/screenshots';
fs.mkdirSync(shotDir, { recursive: true });

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage();
const consoleErrors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error') consoleErrors.push(msg.text());
});
page.on('pageerror', (err) => consoleErrors.push('pageerror: ' + err.message));

async function shot(name) {
  await page.screenshot({ path: `${shotDir}/${name}.png`, fullPage: true });
  console.log('screenshot:', name);
}

try {
  await page.goto('http://localhost:4200/produkte', { waitUntil: 'networkidle' });
  await page.waitForSelector('.product-card', { timeout: 10000 });
  await shot('01-product-list');

  const firstCard = page.locator('.product-card').first();
  const name = await firstCard.locator('h3').innerText();
  console.log('First product:', name);
  await firstCard.click();

  await page.waitForSelector('.purchase-box', { timeout: 10000 });
  await shot('02-product-detail');

  await page.fill('#quantity', '2');
  await page.click('button:has-text("In den Warenkorb")');
  await page.waitForSelector('text=Zum Warenkorb hinzugefügt', { timeout: 5000 });
  await shot('03-added-to-cart');

  // submit a rating too
  await page.fill('#author', 'Testkunde Playwright');
  await page.selectOption('#stars', '4');
  await page.click('button:has-text("Bewertung abschicken")');
  await page.waitForTimeout(1000);
  await shot('04-after-rating');

  await page.click('text=Zum Warenkorb');
  await page.waitForSelector('.cart-table', { timeout: 10000 });
  await shot('05-cart');

  await page.click('a:has-text("Zur Kasse")');
  await page.waitForSelector('#contactName', { timeout: 10000 });
  await page.fill('#contactName', 'Max Mustermann');
  await page.fill('#email', 'max@example.com');
  await page.fill('#street', 'Musterweg 1');
  await page.fill('#postalCode', '12345');
  await page.fill('#city', 'Musterstadt');
  await shot('06-checkout-filled');

  await page.click('button:has-text("Bestellung abschicken")');
  await page.waitForSelector('text=eingegangen', { timeout: 10000 });
  await shot('07-order-confirmation');

  console.log('URL after order:', page.url());
  console.log('Console errors:', JSON.stringify(consoleErrors, null, 2));
} catch (err) {
  console.error('FLOW ERROR:', err);
  await shot('error-state');
  console.log('Console errors so far:', JSON.stringify(consoleErrors, null, 2));
  process.exitCode = 1;
} finally {
  await browser.close();
}

