const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage();
page.on('console', (msg) => console.log('CONSOLE:', msg.type(), msg.text()));
page.on('pageerror', (err) => console.log('PAGEERROR:', err.message));
page.on('requestfailed', (req) => console.log('REQFAILED:', req.url(), req.failure()?.errorText));
page.on('response', (res) => {
  if (res.url().includes('/ratings')) {
    console.log('RESPONSE', res.status(), res.url());
  }
});

await page.goto('http://localhost:4200/produkte/P8', { waitUntil: 'networkidle' });
await page.waitForSelector('.purchase-box');
console.log('before:', await page.locator('.rating-summary').innerText());

await page.fill('#author', 'Verifier');
await page.selectOption('#stars', '3');
await page.click('button:has-text("Bewertung abschicken")');

await page.waitForFunction(
  () => document.querySelector('.rating-summary')?.textContent?.includes('von 5'),
  { timeout: 8000 },
).then(() => console.log('rating summary updated in DOM')).catch((e) => console.log('TIMEOUT waiting for update', e.message));

console.log('after:', await page.locator('.rating-summary').innerText());

await browser.close();

